extends "res://htd/htd_test.gd"


func _run_tests() -> void:
	var player := instantiate_script("res://story/story_player.gd") as Node
	if not check("player_valido", player != null, "StoryPlayer deve potersi istanziare senza errori"):
		return

	if not check("has_jump_chapter", has_function(player, "jump_to_chapter"), "StoryPlayer deve avere la funzione jump_to_chapter(file_path, target_label)"):
		return
	if not check("has_jump_label", has_function(player, "jump_to_label"), "StoryPlayer deve avere la funzione jump_to_label(label_name)"):
		return

	var loaded: bool = bool(player.call("load_story", "res://story/chapters/chapter_01.json"))
	if not check("load_ch1", loaded, "load_story deve caricare correttamente res://story/chapters/chapter_01.json"):
		return

	player.call("start_story")
	# Avanzando dalla prima riga di Elena si attiva il comando jump_chapter
	player.call("advance")

	var current_path: String = String(get_prop(player, "story_file_path", ""))
	check("salto_a_ch2", current_path == "res://story/chapters/chapter_02.json", "Dopo jump_chapter il percorso attivo deve essere chapter_02.json (attuale: %s)" % current_path)

	var line_idx: int = int(get_prop(player, "_current_line_index", -1))
	check("indice_riga_marco", line_idx == 1, "All'arrivo su sala_centrale l'indice deve puntare alla battuta successiva all'etichetta (indice 1, attuale: %d)" % line_idx)

	var fake_jump: bool = bool(player.call("jump_to_label", "etichetta_fantasma"))
	check("etichetta_inesistente_false", fake_jump == false, "jump_to_label deve restituire false se l'etichetta cercata non esiste")

