extends "res://htd/htd_test.gd"


func _run_tests() -> void:
	var player := instantiate_script("res://story/story_player.gd") as Node
	if not check("player_creato", player != null, "StoryPlayer deve potersi istanziare"):
		return

	# 1. Verifica del percorso completo nei capitoli della visual novel
	var jump_ok: bool = bool(player.call("jump_to_chapter", "res://story/chapters/chapter_01.json", "inizio"))
	if not check("salto_a_inizio", jump_ok, "jump_to_chapter deve trovare l'etichetta 'inizio' in chapter_01.json"):
		return

	player.call("advance")
	var path_ch2: String = String(get_prop(player, "story_file_path", ""))
	if not check("gioco_salto_a_ch2", path_ch2 == "res://story/chapters/chapter_02.json", "Dal Capitolo 1 si deve saltare a chapter_02.json (attuale: %s)" % path_ch2):
		return

	player.call("advance")
	var path_ch3: String = String(get_prop(player, "story_file_path", ""))
	if not check("gioco_salto_a_ch3", path_ch3 == "res://story/chapters/chapter_03.json", "Dal Capitolo 2 si deve saltare a chapter_03.json (attuale: %s)" % path_ch3):
		return

	player.call("advance") # battuta di Marco
	player.call("advance") # salto jump_chapter indietro a chapter_01

	var path_ritorno: String = String(get_prop(player, "story_file_path", ""))
	check("gioco_ritorno_ch1", path_ritorno == "res://story/chapters/chapter_01.json", "Dal Capitolo 3 si deve tornare indietro a chapter_01.json (attuale: %s)" % path_ritorno)

	# 2. La piattaforma percorre una storia su tre file propri con salti avanti e indietro
	var dir := DirAccess.open("user://")
	if not check("dir_access", dir != null, "Impossibile accedere alla cartella dati utente"):
		return

	var fa := FileAccess.open("user://test_ch_a.json", FileAccess.WRITE)
	fa.store_string(JSON.stringify({
		"title": "Test A",
		"lines": [
			{"type": "label", "name": "step_a"},
			{"speaker": "A", "text": "Linea A"},
			{"type": "jump_chapter", "target_file": "user://test_ch_b.json", "target_label": "step_b"},
			{"type": "label", "name": "ritorno_a"},
			{"speaker": "A", "text": "Rientro in A"}
		]
	}))
	fa.close()

	var fb := FileAccess.open("user://test_ch_b.json", FileAccess.WRITE)
	fb.store_string(JSON.stringify({
		"title": "Test B",
		"lines": [
			{"type": "label", "name": "step_b"},
			{"speaker": "B", "text": "Linea B"},
			{"type": "jump_chapter", "target_file": "user://test_ch_c.json", "target_label": "step_c"}
		]
	}))
	fb.close()

	var fc := FileAccess.open("user://test_ch_c.json", FileAccess.WRITE)
	fc.store_string(JSON.stringify({
		"title": "Test C",
		"lines": [
			{"type": "label", "name": "step_c"},
			{"speaker": "C", "text": "Linea C"},
			{"type": "jump_chapter", "target_file": "user://test_ch_a.json", "target_label": "ritorno_a"}
		]
	}))
	fc.close()

	player.call("jump_to_chapter", "user://test_ch_a.json", "step_a")
	player.call("advance")
	check("piattaforma_a_a_b", String(get_prop(player, "story_file_path", "")) == "user://test_ch_b.json", "StoryPlayer deve saltare da file A a file B")

	player.call("advance")
	check("piattaforma_b_a_c", String(get_prop(player, "story_file_path", "")) == "user://test_ch_c.json", "StoryPlayer deve saltare da file B a file C")

	player.call("advance")
	check("piattaforma_c_a_a", String(get_prop(player, "story_file_path", "")) == "user://test_ch_a.json", "StoryPlayer deve saltare all'indietro da file C a file A")

	var final_idx: int = int(get_prop(player, "_current_line_index", -1))
	check("piattaforma_target_label", final_idx == 4, "Dopo il salto a ritorno_a l'indice deve essere 4 (attuale: %d)" % final_idx)

	dir.remove("test_ch_a.json")
	dir.remove("test_ch_b.json")
	dir.remove("test_ch_c.json")

